macro_rules! deps {
    () => {
        SampleUniform!();
        Distribution!();
    };
}

macro_rules! WeightedIndex {
    () => {
        deps!();
        # [doc = " A distribution using weighted sampling of discrete items."] # [doc = ""] # [doc = " Sampling a `WeightedIndex` distribution returns the index of a randomly"] # [doc = " selected element from the iterator used when the `WeightedIndex` was"] # [doc = " created. The chance of a given element being picked is proportional to the"] # [doc = " weight of the element. The weights can use any type `X` for which an"] # [doc = " implementation of [`Uniform<X>`] exists. The implementation guarantees that"] # [doc = " elements with zero weight are never picked, even when the weights are"] # [doc = " floating point numbers."] # [doc = ""] # [doc = " # Performance"] # [doc = ""] # [doc = " Time complexity of sampling from `WeightedIndex` is `O(log N)` where"] # [doc = " `N` is the number of weights."] # [doc = " See also [`rand_distr::weighted`] for alternative implementations supporting"] # [doc = " potentially-faster sampling or a more easily modifiable tree structure."] # [doc = ""] # [doc = " A `WeightedIndex<X>` contains a `Vec<X>` and a [`Uniform<X>`] and so its"] # [doc = " size is the sum of the size of those objects, possibly plus some alignment."] # [doc = ""] # [doc = " Creating a `WeightedIndex<X>` will allocate enough space to hold `N - 1`"] # [doc = " weights of type `X`, where `N` is the number of weights. However, since"] # [doc = " `Vec` doesn't guarantee a particular growth strategy, additional memory"] # [doc = " might be allocated but not used. Since the `WeightedIndex` object also"] # [doc = " contains an instance of `X::Sampler`, this might cause additional allocations,"] # [doc = " though for primitive types, [`Uniform<X>`] doesn't allocate any memory."] # [doc = ""] # [doc = " Sampling from `WeightedIndex` will result in a single call to"] # [doc = " `Uniform<X>::sample` (method of the [`Distribution`] trait), which typically"] # [doc = " will request a single value from the underlying [`RngCore`], though the"] # [doc = " exact number depends on the implementation of `Uniform<X>::sample`."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use rand::prelude::*;"] # [doc = " use rand::distr::weighted::WeightedIndex;"] # [doc = ""] # [doc = " let choices = ['a', 'b', 'c'];"] # [doc = " let weights = [2,   1,   1];"] # [doc = " let dist = WeightedIndex::new(&weights).unwrap();"] # [doc = " let mut rng = rand::rng();"] # [doc = " for _ in 0..100 {"] # [doc = "     // 50% chance to print 'a', 25% chance to print 'b', 25% chance to print 'c'"] # [doc = "     println!(\"{}\", choices[dist.sample(&mut rng)]);"] # [doc = " }"] # [doc = ""] # [doc = " let items = [('a', 0.0), ('b', 3.0), ('c', 7.0)];"] # [doc = " let dist2 = WeightedIndex::new(items.iter().map(|item| item.1)).unwrap();"] # [doc = " for _ in 0..100 {"] # [doc = "     // 0% chance to print 'a', 30% chance to print 'b', 70% chance to print 'c'"] # [doc = "     println!(\"{}\", items[dist2.sample(&mut rng)].0);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " [`Uniform<X>`]: crate::distr::Uniform"] # [doc = " [`RngCore`]: crate::RngCore"] # [doc = " [`rand_distr::weighted`]: https://docs.rs/rand_distr/latest/rand_distr/weighted/index.html"] # [derive (Debug , Clone , PartialEq)] # [cfg_attr (feature = "serde" , derive (Serialize , Deserialize))] pub struct WeightedIndex < X : SampleUniform + PartialOrd > { cumulative_weights : Vec < X > , total_weight : X , weight_distribution : X :: Sampler , }
    };
}

WeightedIndex!();